/**
 * Is a Deephaven server reachable at this origin? For pages that run on a real server when there is one and fall
 * back to an in-page mock (@acme/dh-mock) when there isn't. A dev server or preview that proxies /jsapi to
 * Deephaven makes the server's origin the page's own.
 *
 * The JS API file answers GET only; the headers settle it, so the body (several MB) is cut off.
 */
export declare function serverAvailable(origin?: string, timeoutMs?: number): Promise<boolean>;
